# ✅ **9. Delete a Node in BST (All 3 Cases)**  
(from page 21–23 fileciteturn0file0)

**Case 1 → leaf node**  
**Case 2 → one child**  
**Case 3 → two children**

Simplest full working delete function:

```c
struct Node* delete(struct Node* root, int key) {
    if (root == NULL)
        return root;

    // Search
    if (key < root->data)
        root->left = delete(root->left, key);

    else if (key > root->data)
        root->right = delete(root->right, key);

    else {
        // Case 1: no child
        if (root->left == NULL && root->right == NULL) {
            free(root);
            return NULL;
        }

        // Case 2: one child
        else if (root->left == NULL) {
            struct Node* temp = root->right;
            free(root);
            return temp;
        }
        else if (root->right == NULL) {
            struct Node* temp = root->left;
            free(root);
            return temp;
        }

        // Case 3: two children
        struct Node* temp = findMin(root->right);
        root->data = temp->data;
        root->right = delete(root->right, temp->data);
    }

    return root;
}
```

